// src/data/chapterSummaries.ts
import { API_URL } from '../lib/api';
//
// Hardcoded chapter-specific summaries.
// Keys are lowercase, trimmed chapter titles for forgiving matching.
//
// Coverage so far:
//   Class 5  — Math Mela (4 chapters)
//   Class 10 — Physics, Chemistry, Biology, Mathematics (all 30 chapters)
//   Class 11, 12, and junior classes — pending (request next batch)
//
// To add: just drop a new key like "polynomials": `Your 10-15 sentence summary...`
// Syllabus page falls back to chapter.explanation in syllabus.ts when no entry exists here.

export const CHAPTER_SUMMARIES: Record<string, string> = {
  /* ───────────── CLASS 5 — MATHS MELA ───────────── */

  "we the travellers - i": `"We the Travellers — I" is the opening chapter of the Class 5 Maths Mela textbook. It uses the theme of journeys to introduce students to large numbers and how they appear in everyday travel contexts. Children explore stories about travellers covering different distances and learn to compare numbers up to lakhs. The chapter strengthens understanding of place value in the Indian system, including how to read and write numbers like 25,000 and 1,00,000 correctly. Word problems involve calculating total distance covered, comparing the lengths of two journeys, and reading basic maps. Simple multi-digit addition and subtraction is practiced through travel-based situations. Students estimate distances mentally before checking with actual values, building number sense. There are activities around scales on maps, helping students understand that 1 cm on paper can represent many kilometres in reality. The chapter encourages mental math through rounding — for example, estimating a 487 km trip as roughly 500 km. By the end, learners can confidently read, write, compare, and operate with numbers up to one lakh in real-world settings.`,

  "we the travellers - ii": `"We the Travellers — II" continues the journey-based theme from Part I and pushes students into more advanced number work. The focus shifts to operations with larger numbers — addition, subtraction, multiplication, and division applied to travel scenarios. Students calculate total fuel costs for trips, compare prices across modes of transport, and split expenses among groups of travellers. The chapter introduces multi-step word problems where children must decide which operations to use and in what order. Mental strategies are emphasized, like breaking 397 into 400 minus 3 to make subtraction faster. Time is woven in through journey durations, departure and arrival problems, and converting between hours and minutes. Map reading deepens with the introduction of directions, simple coordinates, and route planning. Students explore patterns in travel timetables, finding regular intervals and predicting future entries. Real data from Indian railways, buses, and flights is used in problems to keep them grounded. By the end of the chapter, learners can confidently solve multi-step arithmetic problems set in travel and journey contexts.`,

  "fractions": `The Fractions chapter in Class 5 Maths Mela builds on what students learned in earlier classes about parts of a whole. It begins with visual representations of fractions using familiar shapes — circles, rectangles, and number lines — so children can see what a fraction means before working with it numerically. Students learn to identify and write proper fractions, where the numerator is smaller than the denominator. The chapter then introduces improper fractions like 7/4 and shows how they convert into mixed numbers such as 1¾. Equivalent fractions are explored through paper folding and dividing shapes equally — students discover that 1/2 equals 2/4 equals 4/8. Comparison of fractions is taught using both visual tools and the concept of a common denominator. Simple addition and subtraction of fractions with the same denominator is practiced through real-life examples like sharing a chocolate bar or cutting a cake. The chapter draws connections to daily life — measuring ingredients while cooking, reading time in halves and quarters, and dividing groups of objects fairly. Word problems push students to apply fractions to situations like distributing pencils among friends or finishing parts of a task. By the end, students can name, compare, add, and subtract simple fractions confidently and recognize them in the world around them.`,

  "angles as turns": `"Angles as Turns" introduces Class 5 students to the concept of angles through the everyday idea of turning. The chapter begins by asking students to make different kinds of turns — quarter turn, half turn, three-quarter turn, and full turn — using their bodies, doors, and clock hands. Students learn that an angle is essentially the amount of turn between two arms meeting at a point. Four basic types of angles are introduced: right angle (a quarter turn), straight angle (a half turn), acute angle (less than a right angle), and obtuse angle (between a right and a straight angle). Children compare angles by tracing them on paper and overlapping them, learning to judge size before they ever pick up a measuring tool. The protractor is then introduced as the tool for measuring angles in degrees, with one full turn being 360 degrees. Activities involve spotting angles in real shapes — corners of books, road junctions, hands of a clock at different times of day. Students practice drawing angles of given measurements using a protractor and ruler with care and accuracy. The chapter connects angles to familiar geometric figures, showing how rectangles always have four right angles and how triangles have three angles that sum to 180 degrees. By the end, learners can recognize, classify, measure, and draw angles confidently from 0 to 180 degrees.`,

  /* ───────────── CLASS 10 — PHYSICS ───────────── */

  "light - reflection and refraction": `This chapter is the foundation of Class 10 optics and is heavily tested in CBSE board exams. It begins by recalling the laws of reflection and extending them to spherical mirrors — concave and convex. Students learn the meanings of pole, centre of curvature, principal axis, principal focus, and focal length, with the key relation R = 2f. Ray diagrams are used to predict the position, size, and nature of images formed by mirrors for different object positions, and the mirror formula 1/v + 1/u = 1/f along with magnification m = -v/u is introduced. Refraction is defined as the bending of light when it enters a different medium, governed by Snell's law and the refractive index n = c/v. The chapter develops the lens formula 1/v - 1/u = 1/f and magnification m = v/u for thin convex and concave lenses. Sign conventions for mirrors and lenses are emphasized because most student errors come from getting signs wrong. Real-world applications include the working of car rear-view mirrors, dentist mirrors, magnifying glasses, and shop security mirrors. Numerical problems on image formation, focal length, magnification, and refractive index appear regularly in board papers. Mastering ray diagrams and the sign convention is essential for the higher-mark questions in this chapter.`,

  "the human eye and the colourful world": `This chapter applies the optics from the previous chapter to the human eye and to natural phenomena in the sky. Students study the structure of the human eye — cornea, iris, pupil, lens, retina — and how the ciliary muscles change the lens shape to focus on objects at different distances, a process called accommodation. The chapter explains the four common defects of vision: myopia (short-sightedness), hypermetropia (long-sightedness), presbyopia, and astigmatism, and how each is corrected using concave or convex lenses. Power of a lens is introduced with the formula P = 1/f, measured in dioptres. Refraction through a glass prism is studied next, leading to dispersion — the splitting of white light into seven colours, which is the basis for understanding rainbows. Atmospheric refraction explains why stars twinkle, why the Sun appears earlier and stays later than its actual position at horizon, and the advance and delay of sunrise and sunset. Scattering of light by dust and air molecules explains the blue colour of the clear sky and the red appearance of the Sun at sunrise and sunset. Tyndall effect is mentioned through everyday examples like a beam of light passing through smoke. The chapter is mostly conceptual and easy to score in if students learn diagrams of the eye, lens corrections, and atmospheric phenomena well.`,

  "electricity": `Electricity is one of the highest-weightage chapters in Class 10 Physics for boards. It begins with the concept of electric current as the flow of charge, with the formula I = Q/t and the SI unit ampere. Potential difference is introduced as work done per unit charge, V = W/Q, measured in volts, and the role of a battery as the source of potential difference is explained. Ohm's law V = IR is the central relationship of the chapter, linking voltage, current, and resistance. Factors affecting resistance — length, area of cross-section, nature of material, and temperature — are discussed with the formula R = ρL/A, where ρ is resistivity. Combinations of resistors in series (R_total = R1 + R2 + …) and in parallel (1/R_total = 1/R1 + 1/R2 + …) are derived and applied through circuit problems. Heating effect of current is introduced through Joule's law H = I²Rt, with applications in electric heaters, irons, and the design of fuses. Electric power P = VI = I²R = V²/R is studied along with the kilowatt-hour as the commercial unit of energy. Diagrams of simple circuits, ammeters, voltmeters, and the use of correct symbols are essential exam skills. Numerical problems on resistance, power, and energy consumption are guaranteed in the question paper.`,

  "magnetic effects of electric current": `This chapter connects electricity with magnetism and forms the conceptual basis for motors, generators, and electrical safety in homes. It starts with magnetic fields produced by current-carrying conductors and uses iron filings and the right-hand thumb rule to visualize field patterns around straight wires, circular loops, and solenoids. Students compare a solenoid's field with a bar magnet, leading to the idea that an electric current can produce a magnetic field as strong as a permanent magnet. The force on a current-carrying conductor in a magnetic field is introduced through Fleming's left-hand rule, which determines the direction of force. This rule is then applied to explain the working of an electric motor, with diagrams showing the role of armature, commutator, and brushes. Electromagnetic induction is studied next — moving a magnet near a coil produces a current, captured by Fleming's right-hand rule. The chapter explains the construction and working of an AC generator, the difference between AC and DC, and where each is used. Domestic electric circuits are covered in detail, including live, neutral and earth wires, the role of the earth wire in safety, fuses, MCBs, short circuits, and overloading. Diagrams and rule-applications dominate the assessment in this chapter. Strong understanding of motor and generator diagrams plus Fleming's two rules is enough to score well.`,

  "sources of energy": `This is a relatively short and concept-heavy chapter focused on the different ways humans generate energy and the trade-offs involved. It opens by defining a good source of energy as one that is easy to store, transport, safe, economical, and gives a large amount of energy per unit volume or mass. Conventional sources are discussed first, including fossil fuels (coal, petroleum, natural gas) and how thermal power plants use them to produce electricity. Hydroelectric power is explained through dams and the conversion of potential energy of stored water into electrical energy, along with environmental and displacement concerns. Biomass and improved chulhas, biogas plants, and the chemistry of biogas (mostly methane) are covered with simple plant diagrams. Non-conventional sources include solar energy with solar cookers, solar cells, and solar water heaters, plus wind energy through wind farms and turbines. Energy from the sea — tidal, wave, and ocean thermal energy conversion (OTEC) — is explained briefly. Geothermal energy and nuclear energy are introduced, with nuclear fission and fusion explained at a basic level along with safety and waste-disposal concerns. Each source is evaluated on availability, cost, environmental impact, and sustainability. The chapter rewards students who memorize the working principles, advantages, and disadvantages of each source clearly.`,

  /* ───────────── CLASS 10 — CHEMISTRY ───────────── */

  "chemical reactions and equations": `This is the opening chapter of Class 10 Chemistry and lays the foundation for everything that follows. It begins with how to recognize a chemical reaction through observable changes — colour change, temperature change, gas evolution, precipitate formation, and change in state. Students learn to write chemical equations, balance them by the hit-and-trial method, and add state symbols (s), (l), (g), (aq) and reaction conditions like heat, light, or catalyst. Five major types of reactions are introduced: combination, decomposition, displacement, double displacement, and redox reactions, each with classic examples like burning of magnesium, electrolysis of water, and reaction of zinc with copper sulphate. Oxidation is defined as gain of oxygen or loss of hydrogen, and reduction as the opposite, with the idea that both happen together in a redox reaction. Exothermic and endothermic reactions are illustrated through respiration and photosynthesis. Real-life effects of redox reactions are emphasized — corrosion of iron (rusting) and rancidity of food, along with simple prevention methods. Practical applications include why food is packed in nitrogen, how silver tarnishes, and why iron pipes are painted. Diagrams of laboratory setups for decomposition reactions and the activity of metals appear frequently in exams. Mastering balancing and identifying reaction types is essential before moving to later chapters.`,

  "acids, bases and salts": `This chapter explores the chemistry of three of the most important categories of compounds — acids, bases, and salts — through their properties, reactions, and uses. Students begin with indicators (litmus, methyl orange, phenolphthalein, turmeric, red cabbage) and how they change colour with acids and bases. Properties of acids are covered through reactions with metals (giving hydrogen gas), metal carbonates and bicarbonates (giving carbon dioxide), and bases (neutralisation). Bases are studied similarly, including how non-metal oxides like CO2 react with bases to form salts. The role of water is explained through dissociation of acids and bases into H+ and OH- ions and the universal pH scale from 0 to 14. The importance of pH in everyday life is emphasized — tooth decay below pH 5.5, soil pH for crops, antacids for stomach acidity, and bee stings versus wasp stings. Common salts are discussed in detail: sodium chloride, sodium hydroxide (chlor-alkali process), bleaching powder, baking soda, washing soda, and plaster of Paris, along with their preparations, properties, and uses. The water of crystallisation concept is introduced through hydrated salts like CuSO4·5H2O. The chapter blends conceptual understanding with factual content and is highly scoring if students prepare salt-related uses and reactions thoroughly. Exam questions often combine equations, indicator behaviour, and practical applications in one problem.`,

  "metals and non-metals": `This chapter contrasts the physical and chemical properties of metals and non-metals and lays the groundwork for understanding bonding and metallurgy. Physical properties — lustre, malleability, ductility, conductivity, sonority, and high melting points — are first listed for metals, then contrasted with non-metals which are usually dull, brittle, and poor conductors. Chemical properties of metals include reactions with oxygen (forming basic oxides), water, acids, and other metal salts, with the activity series of metals introduced as a way to predict displacement reactions. Properties of non-metals include reactions with oxygen (forming acidic oxides) and reactivity differences, with examples like sulphur, chlorine, and oxygen. Ionic bonding is introduced through the formation of compounds like sodium chloride, with electron-dot diagrams showing transfer of electrons between metals and non-metals. Properties of ionic compounds — high melting points, solubility in water, conductivity in molten or aqueous state — are discussed. Metallurgy is a large part of the chapter, covering the steps of extraction: enrichment of ore, conversion to oxide (roasting and calcination), reduction to metal, and refining (electrolytic refining is shown with diagram). Reactivity of metals decides the extraction method, with low-reactivity metals like gold extracted by displacement and high-reactivity metals like sodium by electrolysis. Corrosion of iron and methods to prevent it (galvanisation, alloying, painting) are revisited with applications. Alloys like brass, bronze, stainless steel, and amalgams are listed with their compositions and uses. The chapter is highly factual but also requires diagram and equation accuracy in exams.`,

  "carbon and its compounds": `This chapter introduces organic chemistry at a Class 10 level, focusing on carbon's unique ability to form a vast number of compounds through covalent bonds. The chapter begins with the nature of covalent bonding, with electron-dot structures of common molecules like H2, O2, N2, CH4, and water. Catenation — the ability of carbon to form long chains, branched chains, and rings — and tetravalency are explained as the two main reasons for the diversity of carbon compounds. Saturated hydrocarbons (alkanes) and unsaturated hydrocarbons (alkenes and alkynes) are covered with structural formulas, IUPAC nomenclature for the first ten alkanes, and the concept of homologous series. Functional groups — halogen, alcohol, aldehyde, ketone, carboxylic acid — are introduced briefly with examples and naming rules. Important chemical properties are studied: combustion (with clean blue and sooty yellow flames), oxidation of alcohols by alkaline KMnO4 or acidified K2Cr2O7, and addition of hydrogen to unsaturated hydrocarbons in the presence of nickel catalyst. Substitution reactions of alkanes with chlorine in sunlight are discussed with the methane example. Two specific compounds get detailed treatment: ethanol and ethanoic acid, including their preparation, physical properties, chemical reactions (ethanol burning, dehydration; ethanoic acid esterification, neutralisation), and uses. Soaps and detergents are covered with the difference in their structure and how they act on hard water, plus the formation of micelles around dirt particles. The chapter is concept-rich and scoring when students master IUPAC names, functional groups, and the few key reactions.`,

  "periodic classification of elements": `This chapter is the historical and conceptual journey of how chemists organized the elements into the modern periodic table. It begins with Dobereiner's triads, where three elements with similar properties showed an arithmetic relationship in atomic masses. Newlands' law of octaves followed, with limitations beyond calcium and the failure to accommodate noble gases. Mendeleev's periodic table is studied in depth — its arrangement by atomic mass, the periodic law, and how he left gaps for undiscovered elements like gallium and germanium and predicted their properties accurately. Limitations of Mendeleev's table are listed, including the position of hydrogen, isotopes, and certain anomalous orderings (like Co before Ni). The modern periodic law is then introduced — properties of elements are a periodic function of atomic numbers, leading to the modern long-form table with 18 groups and 7 periods. Trends in the modern periodic table are explained: atomic size decreases across a period and increases down a group, metallic character decreases across a period and increases down a group, and valency follows clear patterns based on group number. Position of hydrogen is discussed since it shares properties with both Group 1 and Group 17. The chapter blends history, classification, and trend-based reasoning, and is one of the more conceptual chemistry chapters in Class 10. Scoring well requires comfort with trends and the ability to predict properties from a position in the periodic table.`,

  /* ───────────── CLASS 10 — BIOLOGY ───────────── */

  "life processes": `Life Processes covers the four basic processes that maintain life in any organism: nutrition, respiration, transportation, and excretion. The chapter opens with autotrophic nutrition in plants (photosynthesis), explaining the raw materials, the role of chlorophyll, the equation 6CO2 + 6H2O → C6H12O6 + 6O2 in sunlight, and experiments like the iodine test for starch. Heterotrophic nutrition is then explored through the human digestive system — diagram, organs, glands, enzymes, and the journey of food from mouth to anus, with emphasis on enzymes like amylase, pepsin, trypsin, and bile's role in fat emulsification. Respiration is divided into aerobic (giving CO2, water, and lots of energy) and anaerobic (giving lactic acid in muscles or ethanol in yeast), with the human respiratory system including alveoli and gas exchange covered with a clear diagram. Transportation in humans focuses on the heart, blood vessels (arteries, veins, capillaries), double circulation, and the role of platelets, RBCs, and plasma. Transportation in plants is covered through xylem (water and minerals, by transpiration pull) and phloem (food, by translocation), distinguishing the two clearly. Excretion in humans centres on the kidney, with the structure of a nephron, filtration in the Bowman's capsule, reabsorption in the tubules, and the excretory product urea explained step by step. Excretion in plants is touched on through transpiration, oxygen release, and storage of waste in leaves and bark. Diagrams are central to scoring in this chapter — the human heart, alveoli, nephron, and digestive tract appear in board exams almost every year. Strong understanding of how each process supports the other is what separates a high scorer from an average one.`,

  "control and coordination": `This chapter explains how living organisms detect changes in their environment and respond to them, focusing on the nervous and hormonal systems in animals and on movements in plants. The structure of a neuron — dendrites, cell body, axon, and synapse — is studied first, with how nerve impulses travel and how chemicals are released at the synapse. Reflex actions are explained through the reflex arc, with classic examples like pulling the hand away from a hot object, contrasting reflexes with conscious actions controlled by the brain. The human nervous system is divided into central nervous system (brain and spinal cord) and peripheral nervous system, with detailed diagrams of the brain regions — fore-, mid-, and hindbrain — and their functions. The cerebellum's role in posture, the medulla's role in involuntary actions, and the cerebrum's role in voluntary actions and intelligence are clearly distinguished. The endocrine system is studied next, with major glands (pituitary, thyroid, pancreas, adrenal, testes, ovaries) and their hormones (growth hormone, thyroxin, insulin, adrenaline, testosterone, oestrogen) with one or two key functions each. The feedback mechanism, illustrated through insulin and blood sugar, shows how the body maintains homeostasis. Plant movements are divided into tropic (directional, slow, growth-related — phototropism, geotropism, hydrotropism, chemotropism) and nastic (non-directional, quick, like the Mimosa response). Plant hormones — auxin, gibberellin, cytokinin, abscisic acid — and their broad functions are listed. Diagrams of the neuron, brain, and reflex arc are essential exam preparation. The chapter rewards memory of glands and hormones combined with understanding of how systems coordinate.`,

  "how do organisms reproduce?": `This chapter introduces the biology of reproduction in both plants and animals, with special focus on human reproduction. It begins with why organisms reproduce and the importance of variation — DNA copying with small errors is the basis of evolution and biodiversity. Asexual reproduction is covered with multiple examples: fission in amoeba, multiple fission in plasmodium, budding in yeast and hydra, fragmentation in spirogyra, regeneration in planaria, vegetative propagation in plants like rose and sugarcane, and spore formation in rhizopus. Sexual reproduction in flowering plants is studied through the structure of a flower, with diagrams showing stamen (anther, filament), carpel (stigma, style, ovary), and the steps of pollination, fertilisation, and seed and fruit formation. Self-pollination and cross-pollination are distinguished with examples. Sexual reproduction in humans is treated in detail: the male reproductive system (testes, vas deferens, seminal vesicles, prostate, penis) and the female reproductive system (ovaries, fallopian tubes, uterus, vagina) with clear diagrams. Puberty changes in girls and boys are described, along with the menstrual cycle and what happens during pregnancy, including the role of the placenta and umbilical cord. Reproductive health is given equal weight, covering contraception methods (barrier, hormonal, surgical), sexually transmitted infections like AIDS, and the social issues of female foeticide and prenatal sex determination, which are illegal in India. The chapter blends factual content with diagrams and is one of the most scoring biology chapters when students study reproductive system diagrams and definitions thoroughly.`,

  "heredity": `Heredity introduces students to the science of how traits pass from parents to offspring, building on Mendel's classic experiments. It starts by distinguishing inherited traits from acquired ones — a child can inherit eye colour from parents, but a parent's swimming skill is not passed on. Mendel's experiments with pea plants are studied in detail, beginning with monohybrid crosses on traits like tallness and dwarfness, leading to the 3:1 ratio in F2 generation and the rules of dominance and segregation. Dihybrid crosses on two traits at once give the 9:3:3:1 ratio and the law of independent assortment. Genes, alleles, dominant and recessive traits, homozygous and heterozygous genotypes, and the difference between phenotype and genotype are introduced with clear examples. Sex determination in humans is then explained — the X and Y chromosomes, with the father's gamete deciding the sex of the child since the mother contributes only X. The fact that the sex of the baby is determined by the father (genetically) is emphasized to clear common misconceptions. The chapter ties Mendelian inheritance back to DNA — genes are segments of DNA carrying information for traits. Variation as the raw material for evolution is briefly introduced, connecting to the next bigger story of natural selection (covered in Class 12). Diagrams of Punnett squares, the Mendel cross results, and sex determination are common exam favourites. Students who can solve simple genetic crosses confidently score very well in this chapter.`,

  "our environment": `Our Environment focuses on ecosystems, the flow of energy and matter through them, and human impact on the natural world. The chapter opens with the components of an ecosystem — biotic (producers, consumers, decomposers) and abiotic (light, temperature, water, soil) — and how they interact. Food chains are introduced with examples like grass → grasshopper → frog → snake → eagle, and food webs are shown to be more realistic than linear chains. The 10 percent law of energy transfer is explained, illustrating why food chains rarely have more than four or five trophic levels. Decomposers like bacteria and fungi are studied for their critical role in nutrient recycling. Human impact is covered next, focusing on two major issues: ozone layer depletion and waste management. Ozone, formed from oxygen by UV radiation high in the atmosphere, protects life on Earth from harmful UV radiation; CFCs released from refrigerators and aerosols deplete it, with the Montreal Protocol introduced as the international response. Biodegradable and non-biodegradable wastes are distinguished, with examples of each and the long-term ecological harm of non-biodegradable substances like plastics. The chapter ends with simple actions students can take in daily life — segregating waste, reducing single-use plastics, planting trees, and saving energy. Diagrams of food chains, food webs, and energy pyramids are common in exams. The chapter is short and easy to score in if students prepare definitions and the ozone story carefully.`,

  "sustainable management of natural resources": `This chapter takes a wider lens on the environment and asks how humans can use resources without destroying them for future generations. It starts by introducing sustainable development and the concept of the three Rs — Reduce, Reuse, Recycle — applied to electricity, water, paper, and plastics in daily life. Forests are explored as a resource with multiple stakeholders: local people, the forest department, industries, and conservationists, each with their own claims. Case studies on forest conservation are featured, especially the Chipko movement (Himalayan villagers hugging trees to protect them) and people's participation in forest management in Arabari, West Bengal. Water as a resource is covered through the importance of rivers, dams, and the failure of large dams to meet local needs sustainably; the chapter highlights traditional water harvesting systems like khadins, tanks, bawris, and the concept of watershed management. Coal and petroleum as fossil fuels are studied — their formation over millions of years, finite reserves, and environmental issues from burning them like CO2 emission and global warming. The chapter argues for using fossil fuels efficiently — switching to public transport, fuel-efficient vehicles, energy-saving appliances, and renewable alternatives. Examples of NGO and community-led conservation throughout India give students a sense of real action being taken. The chapter is a bridge between science and citizenship, encouraging informed environmental decisions. It is short, factual, and easy to score with clear notes on case studies, the three Rs, and the four resources covered.`,

  /* ───────────── CLASS 10 — MATHEMATICS ───────────── */

  "real numbers": `Real Numbers is the opening chapter of Class 10 Mathematics and revisits and deepens the number system. It begins with Euclid's division lemma — for any two positive integers a and b, there exist unique integers q and r such that a = bq + r where 0 ≤ r < b. This lemma is then used in Euclid's division algorithm to find the HCF of two positive integers, with worked examples like HCF of 135 and 225. The Fundamental Theorem of Arithmetic is the centerpiece — every composite number can be expressed as a unique product of primes, apart from the order of factors. This theorem is applied to find HCF and LCM of two or three numbers using prime factorisation, with the relationship HCF × LCM = product of two numbers. Irrational numbers are revisited with rigorous proofs that √2, √3, and √5 are irrational using the proof by contradiction technique. The chapter then studies the decimal expansions of rational numbers — they either terminate or repeat — and identifies which rationals have terminating decimals using the prime factorisation of the denominator (only 2s and 5s give terminating decimals). Examples like 13/3125 versus 17/30 are worked out to drive the point home. The chapter has limited variety of question types in board exams but appears almost every year, especially HCF/LCM word problems and proofs of irrationality. Practice with the standard proofs and a few good word problems is enough to score full marks here.`,

  "polynomials": `Polynomials extends the basic algebra learned earlier into a more structured study of expressions in one variable. The chapter starts by recalling what a polynomial is and defining its degree — the highest power of the variable. Linear (degree 1), quadratic (degree 2), and cubic (degree 3) polynomials are introduced with general forms ax + b, ax² + bx + c, and ax³ + bx² + cx + d respectively. Geometric meaning of zeros of a polynomial is shown — the x-coordinates of the points where the graph cuts the x-axis. The relationship between zeros and coefficients of a quadratic polynomial is studied: sum of zeros = -b/a and product of zeros = c/a, with extension to cubic polynomials. These relationships are used to construct polynomials given their zeros, and to find one zero when the other is known. The division algorithm for polynomials is explained, parallel to the integer division algorithm: p(x) = g(x) × q(x) + r(x), where degree of r(x) is less than degree of g(x). Long division of polynomials is demonstrated with multiple worked examples, and the algorithm is used to find the other zeros of a polynomial when some are known. Graphical representation of linear and quadratic polynomials helps cement understanding visually. The chapter also includes the special case of finding zeros when a polynomial is given in expanded form. Polynomials is a short and high-scoring chapter where practice with the relationship between zeros and coefficients and the division algorithm yields full marks.`,

  "pair of linear equations in two variables": `This chapter studies systems of two linear equations like a1x + b1y + c1 = 0 and a2x + b2y + c2 = 0, and methods to solve them. It begins by recalling a single linear equation and extending to a pair, with the geometric idea that each equation represents a line and the solution is their intersection point. Three cases are identified based on the ratio of coefficients: unique solution (intersecting lines), no solution (parallel lines), and infinitely many solutions (coincident lines), determined by comparing a1/a2, b1/b2, c1/c2. Four algebraic methods of solving are studied — graphical method, substitution method, elimination method, and cross-multiplication method — each demonstrated with multiple examples. Word problems are a major part of this chapter, covering scenarios like ages of two people, cost of items, speed-distance-time problems involving boats in streams or trains, and ratios of fractions. Each problem requires students to translate words into two equations carefully, then solve using their preferred method. Equations reducible to linear form (like 2/x + 3/y = 13) are introduced with substitution u = 1/x, v = 1/y. The chapter is heavy on practice and rewards students who can quickly choose the most efficient method for a given problem. Graphical questions also appear, where students must plot two lines and identify the solution from the graph. Word problems in particular are commonly worth 4 or 6 marks each in CBSE board exams, making this chapter important to master.`,

  "quadratic equations": `Quadratic Equations is a high-weightage chapter that builds critical algebraic skills used in higher classes and entrance exams. It opens by defining a quadratic equation as one of the form ax² + bx + c = 0 where a ≠ 0, and identifying the values of x that satisfy it — the roots. Three methods of solving quadratic equations are studied. The first is factorisation, where the quadratic is split into two linear factors (split-the-middle-term method or directly), worked through many examples like x² - 5x + 6 = 0. The second is completing the square, which converts ax² + bx + c into a(x + p)² + q form. The third is the quadratic formula x = (-b ± √(b²-4ac)) / 2a, derived from completing the square in general. The discriminant D = b² - 4ac is introduced as the deciding factor for the nature of roots: D > 0 gives two distinct real roots, D = 0 gives equal real roots, and D < 0 gives no real roots. Word problems form a major part of this chapter — ages of people, dimensions of rectangles or fields, time taken in journeys with constant changes, and number-related problems like consecutive integers whose product is given. Each word problem requires students to set up the quadratic equation correctly before solving. The chapter ends with applications and reasoning based on the discriminant. With rigorous practice on factorisation tricks, the formula, and word problem setups, students can confidently score full marks.`,

  "arithmetic progressions": `Arithmetic Progressions (AP) introduces students to one of the simplest and most useful types of number patterns. An AP is defined as a sequence where each term differs from the previous by a constant called the common difference d, like 2, 5, 8, 11, … with d = 3. The general term or nth term formula, an = a + (n - 1)d, is derived and used extensively, where a is the first term. Students learn to identify whether a given sequence is an AP, find any specific term given a and d, and find a, d, or n given other information. The sum of the first n terms is the second key formula: Sn = n/2 [2a + (n-1)d] = n/2 (a + l), where l is the last term. Both formulas are applied through dozens of variations — find the sum of the first 50 odd numbers, find which term of an AP is 100, find an AP given two terms, and so on. Word problems involve real situations like saving an increasing amount each month, increasing salaries, falling stones, and stacking objects in a triangular pattern. The chapter emphasizes derivation and the logic behind each formula, not just memorization. Geometric Progressions are mentioned briefly but the focus stays on AP. The chapter is highly formula-driven and scoring for students who memorize the two main formulas and practice their applications well.`,

  "triangles": `Triangles is the geometry chapter that proves and applies the fundamental similarity theorems used in higher mathematics. It begins by recalling congruence of triangles and contrasting it with similarity, where corresponding angles are equal and corresponding sides are proportional. The Basic Proportionality Theorem (also called Thales theorem) is proved: if a line is drawn parallel to one side of a triangle to intersect the other two sides at distinct points, the other two sides are divided in the same ratio. The converse of BPT is also proved and applied. Similarity criteria for triangles are introduced — AAA (or equivalently AA), SSS, and SAS — and used to identify similar triangles in figures and prove relationships between their sides. The Pythagoras theorem is given a fresh proof using similar triangles, and its converse is also stated and proved. The relationship between the areas of two similar triangles is the centerpiece result: it equals the square of the ratio of any pair of corresponding sides. Many proofs and riders combine BPT, similarity criteria, and the area-ratio result, requiring careful diagram drawing and step-wise argumentation. Numerical applications include shadows, ladders, ramps, and trigonometric setups using right triangles. The chapter has a high concentration of theorem-based questions in board exams, including 4-mark and 6-mark proof questions. Students who master the proofs and the area-ratio result can confidently tackle the entire chapter.`,

  "coordinate geometry": `Coordinate Geometry connects algebra with geometry by representing points and lines on the Cartesian plane. The chapter begins by recalling the four quadrants and how each point has unique coordinates (x, y). The distance formula, derived from the Pythagoras theorem, gives the distance between two points (x1, y1) and (x2, y2) as √((x2-x1)² + (y2-y1)²). This formula is used to find distances, prove that three points form an isosceles or right or equilateral triangle, and check if four points form a parallelogram, rhombus, or square. The section formula gives the coordinates of a point dividing the line joining (x1, y1) and (x2, y2) in the ratio m:n internally as ((mx2 + nx1)/(m+n), (my2 + ny1)/(m+n)). Special cases include the midpoint formula (when ratio is 1:1) and finding the centroid of a triangle as the average of vertex coordinates. Students apply these formulas to find unknown coordinates given conditions, divide line segments in given ratios, and find centroids and points of trisection. The chapter is mostly mechanical once the formulas are clear, but offers many variations through word problems and proof-style questions. Practical examples include finding distances on a city map, dividing land into equal parts, and locating midpoints of routes. Coordinate Geometry is a high-scoring chapter in board exams, with most questions following one of a few standard patterns. Disciplined practice with the distance and section formulas is enough to master this chapter.`,

  "introduction to trigonometry": `Introduction to Trigonometry is the gateway to one of the most powerful tools in mathematics, and Class 10 lays the foundation by studying trigonometric ratios in right-angled triangles. The six trigonometric ratios — sine, cosine, tangent, cosecant, secant, cotangent — are defined as ratios of sides of a right triangle relative to a chosen acute angle. The chapter then derives the values of these six ratios for the standard angles 0°, 30°, 45°, 60°, and 90° using equilateral and isosceles right triangles, and these values are tabulated and memorized. Trigonometric ratios of complementary angles are introduced — sin(90° - A) = cos A, cos(90° - A) = sin A, tan(90° - A) = cot A, and so on — and used to simplify expressions. The three fundamental Pythagorean identities — sin²A + cos²A = 1, 1 + tan²A = sec²A, and 1 + cot²A = cosec²A — are derived and proved using the Pythagoras theorem. Most board questions ask students to prove a given trigonometric identity using algebraic manipulation and the three fundamental identities. Numerical evaluation questions are also common — substituting values of standard angles to compute expressions like 2 sin 60° cos 30° + tan² 45°. The chapter has clear patterns, and students who memorize the standard angle values and identities, and practice 20 to 30 identity-proof questions, can score full marks. The skills built here are immediately used in the next chapter on applications of trigonometry. It is one of the most important and exam-relevant chapters in Class 10 Math.`,

  "some applications of trigonometry": `This chapter takes the trigonometric ratios from the previous chapter and applies them to real-world height and distance problems. The two key concepts are angle of elevation (looking up at an object above the horizontal) and angle of depression (looking down at an object below the horizontal), and students must learn to identify them correctly in problem statements. Most problems involve a tower, building, hill, or aeroplane viewed from a point or two points, with a straight line drawn from the eye to the object. Standard scenarios include finding the height of a tree given the shadow length and sun angle, the height of a tower from the angle and horizontal distance, and the distance from a ship to a lighthouse. Problems also involve two observers at different positions, two-step problems where a flagpole sits on top of a building, and angle-of-elevation-at-different-times type problems. Diagrams are everything in this chapter — students must draw the right triangle with the angle clearly marked and the sides labeled (opposite, adjacent, hypotenuse) before applying tan, sin, or cos. Calculations almost always use the standard angle values 30°, 45°, and 60°, so √3 and 1/√3 appear constantly. The chapter is short, formula-light, and very scoring once students are comfortable identifying which side and which trigonometric ratio to use. Practice with 15-20 varied problems builds the diagram-drawing reflex needed for the exam. Most CBSE board papers carry one 4 or 6 mark application question from this chapter every year.`,

  "circles": `Circles in Class 10 focuses specifically on tangents — lines that touch a circle at exactly one point. The chapter begins by recalling chords, secants, arcs, and the properties of perpendicular from the centre to a chord. The two foundational tangent theorems are proved here. First, the tangent at any point of a circle is perpendicular to the radius through the point of contact — this is the most-used result in the chapter. Second, the lengths of two tangents drawn from an external point to a circle are equal. Both theorems are used to prove a wide variety of riders, where students must apply right-triangle properties, congruence, or the Pythagoras theorem to find unknown angles or lengths. Standard problems involve tangents from a point, two tangents intersecting outside the circle, and quadrilaterals circumscribing a circle (where opposite sides have equal sums). Some problems combine triangles and circles — for instance, an inscribed triangle with tangents drawn at its vertices. The proofs themselves can be 3 or 4 mark questions, while application-based questions tend to be 3 or 4 mark numerical or rider problems. Diagram quality matters a lot here, since miss-labelled tangents and angles lead to wrong solutions. The chapter is short with limited theorem variety, making it one of the most scoring geometry chapters when prepared well. Mastering the two main theorems and practicing 10-15 standard riders is enough for full marks in board exams.`,

  "areas related to circles": `This chapter builds on the area and circumference formulas of a circle and extends them to portions like sectors and segments. It begins by recalling area = πr² and circumference = 2πr, then introduces a sector — a region bounded by two radii and an arc, like a pizza slice. The area of a sector subtending angle θ at the centre is (θ/360°) × πr², and the length of its arc is (θ/360°) × 2πr. A segment of a circle is defined as the region between a chord and an arc, with the area of a segment found by subtracting the area of the corresponding triangle from the area of the sector. Common problems involve finding shaded regions in figures with multiple circles, sectors, triangles, and rectangles combined — for example, a square with quadrants drawn at each corner, or a circle inscribed in a square. The chapter requires careful identification of which parts to add and which to subtract to compute the shaded area. Real-world examples include grazing areas of tied animals (where a horse tied to a corner can graze a quarter-circle region), area of clock hands sweeping, and decorative tile patterns. Calculations usually involve substituting π = 22/7 or 3.14 and the standard angle values. The chapter is formula-light but visually demanding — students must read figures carefully and decompose them into known shapes. It is consistently scoring with practice on 10-15 varied composite-figure problems. Most CBSE board papers include at least one shaded-region question from this chapter.`,

  "surface areas and volumes": `This chapter extends the mensuration concepts from earlier classes to more complex 3D shapes and combinations of solids. It starts by recalling the surface area and volume formulas for cuboid, cube, cylinder, cone, sphere, and hemisphere — each formula is listed with units and visualised through diagrams. The main learning is computing the surface area and volume of combinations of two or more solids, like a hemisphere on top of a cylinder (a tent or a capsule), a cone surmounted on a hemisphere (an ice cream cone), or a cylinder with conical ends (a spindle). For surface area, the rule is to add the curved surface areas of exposed parts and subtract any covered area. For volume, the rule is simpler — just add the volumes of all components. Conversion of solids from one shape to another (like melting a metallic sphere and recasting it as a cylinder) uses the principle that volume remains constant. Frustum of a cone — the truncated cone left after slicing the top — is introduced with its own slant height, curved surface area, total surface area, and volume formulas. Word problems involve real objects like buckets (frustums), water tanks (cylinders or combinations), funnels, gulab jamuns, capsules, and so on. Calculations get long, so students must be careful with units and π substitution. This chapter is scoring with disciplined practice on 15-20 varied combination problems. Surface Areas and Volumes consistently appears in CBSE board exams with 4-mark and 6-mark questions.`,

  "statistics": `Statistics in Class 10 deals with measures of central tendency and graphical representation of grouped data. It begins by recalling mean, median, and mode for ungrouped data, then extends each to grouped frequency distributions. The mean of grouped data is computed by three methods: direct method (Σfx/Σf), assumed mean method (a + Σfd/Σf where d = x - a), and step-deviation method (a + h × Σfu/Σf where u = (x-a)/h). The choice of method depends on the size of the numbers — assumed mean and step-deviation simplify large calculations. The median of grouped data uses the formula median = l + ((n/2 - cf)/f) × h, where l is the lower limit of the median class, n is the total frequency, cf is the cumulative frequency before the median class, f is the frequency of the median class, and h is the class size. The mode of grouped data uses mode = l + ((f1 - f0) / (2f1 - f0 - f2)) × h, where f1 is the frequency of the modal class, f0 the previous, and f2 the next. The empirical relationship 3 Median = Mode + 2 Mean is also stated. Cumulative frequency curves (less than and more than ogives) are drawn on graph paper, and the median is read off as the x-coordinate where the two ogives intersect. Real data examples include exam scores, daily wages, plant heights, and rainfall measurements. The chapter is calculation-heavy but very rule-based — once the formulas are memorized and applied carefully, full marks are easy. Most board papers carry one 4 or 6 mark statistics question, so this chapter is a guaranteed scorer.`,

  "probability": `Probability is the closing chapter of Class 10 Math and introduces the formal study of chance. It begins with the classical definition: the probability of an event E is P(E) = (Number of favourable outcomes) / (Total number of equally likely outcomes), with the understanding that 0 ≤ P(E) ≤ 1. Standard examples come from tossing coins (one, two, or three at a time), rolling one or two dice, and drawing cards from a standard 52-card deck. Students learn the composition of a deck (4 suits, 13 cards each, with 12 face cards and 4 aces) and compute probabilities of drawing red cards, queens, face cards, or specific combinations. Probability of the complementary event is introduced with P(not E) = 1 - P(E), which often simplifies calculations. Sure events have probability 1, impossible events have probability 0, and the sum of probabilities of all elementary outcomes is always 1. Common problem types include probability of getting at least one head in three tosses, probability that the sum of two dice equals a specific number, probability of drawing a specific suit from a deck, and probability problems involving balls of different colours in a bag. Word problems also involve real-life randomness like a delayed train, a defective item from a batch, and a randomly chosen day of the week. The chapter is short and one of the easiest in Class 10 Math, with full marks within reach for any student who memorizes the deck composition and practices 15-20 varied questions. CBSE board exams almost always include 1, 2, or 3 mark questions from probability.`,
};

/* =====================================================================
 * BACKEND-CACHED FALLBACK
 * ---------------------------------------------------------------------
 * Hardcoded `CHAPTER_SUMMARIES` covers a handful of classes. Rather than
 * hardcoding 200+ summaries, anything not in CHAPTER_SUMMARIES is fetched
 * on demand from /api/chapter-summary, which itself caches in Firestore.
 *
 * This means: every chapter has a summary, generation happens at most
 * ONCE across all users, and there's no localStorage involved — the
 * cache lives in Firestore and is shared between every visitor.
 *
 * USAGE:
 *
 *   // Sync (immediate paint with hardcoded or fallback):
 *   const summary = getChapterSummary(chapter.title, chapter.explanation);
 *
 *   // Async (fills in missing summaries from the backend):
 *   const summary = await ensureChapterSummary({
 *     classLevel: chapter.classLevel,
 *     subject: chapter.subject,
 *     chapterTitle: chapter.title,
 *     chapterId: chapter.id,
 *     fallback: chapter.explanation,
 *   });
 * ===================================================================== */

// In-memory cache for the current page session — avoids re-fetching the
// same chapter summary multiple times within a single navigation.
const _memCache: Map<string, string> = new Map();
const _inflight: Map<string, Promise<string>> = new Map();

// Concurrency limiter — at most 6 backend calls in-flight at a time so a
// freshly opened class with 30 chapters doesn't smash the backend.
const MAX_CONCURRENT = 6;
let _active = 0;
const _waiters: Array<() => void> = [];

function acquireSlot(): Promise<void> {
  if (_active < MAX_CONCURRENT) {
    _active++;
    return Promise.resolve();
  }
  return new Promise<void>((resolve) => {
    _waiters.push(() => {
      _active++;
      resolve();
    });
  });
}

function releaseSlot() {
  _active = Math.max(0, _active - 1);
  const next = _waiters.shift();
  if (next) next();
}

function resolveApiBase(): string {
  if (typeof window !== 'undefined' && (window as any).__PADHAI_API__) {
    return (window as any).__PADHAI_API__;
  }
  return API_URL;
}

function summaryKey(title: string): string {
  return title
    .trim()
    .toLowerCase()
    .replace(/^[\s\d.()\-–—]+/, '')
    .replace(/[“”"]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Synchronous lookup. Returns:
 *   1. hardcoded summary if present in CHAPTER_SUMMARIES, else
 *   2. in-memory cached AI summary (already fetched this session), else
 *   3. caller-supplied fallback (usually chapter.explanation), else
 *   4. empty string.
 *
 * Never makes a network call. Pair with `ensureChapterSummary` to fetch
 * missing summaries from the backend.
 */
export function getChapterSummary(title: string, fallback?: string): string {
  if (!title) return fallback || '';
  const key = summaryKey(title);
  if (CHAPTER_SUMMARIES[key]) return CHAPTER_SUMMARIES[key];
  const cached = _memCache.get(key);
  if (cached) return cached;
  return fallback || '';
}

/**
 * Async fetcher. Returns the best summary available, fetching from the
 * backend (which caches in Firestore) the first time a chapter is seen.
 *
 * Idempotent: hardcoded and cached summaries return immediately without
 * a network call. Inflight calls for the same chapter are deduped.
 */
export async function ensureChapterSummary(args: {
  classLevel: string | number;
  subject: string;
  chapterTitle: string;
  chapterId?: string;
  fallback?: string;
  apiBase?: string;
}): Promise<string> {
  const { chapterTitle, classLevel, subject, chapterId, fallback } = args;
  if (!chapterTitle) return fallback || '';

  const key = summaryKey(chapterTitle);

  // 1. hardcoded
  if (CHAPTER_SUMMARIES[key]) return CHAPTER_SUMMARIES[key];

  // 2. in-memory session cache
  const memHit = _memCache.get(key);
  if (memHit) return memHit;

  // 3. dedupe inflight
  const inflight = _inflight.get(key);
  if (inflight) return inflight;

  const apiBase = args.apiBase || resolveApiBase();

  const promise = (async () => {
    await acquireSlot();
    try {
      const res = await fetch(`${apiBase}/api/chapter-summary`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          classLevel: String(classLevel),
          subject,
          chapterTitle,
          chapterId: chapterId || chapterTitle,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      const summary = typeof data?.summary === 'string' ? data.summary.trim() : '';
      if (summary) {
        _memCache.set(key, summary);
        return summary;
      }
      return fallback || '';
    } catch (err) {
      console.warn('ensureChapterSummary failed for', chapterTitle, err);
      return fallback || '';
    } finally {
      releaseSlot();
      _inflight.delete(key);
    }
  })();

  _inflight.set(key, promise);
  return promise;
}
